import random, subprocess, sys, tempfile
from pathlib import Path
REFERENCE='# External reference: statistics page /practice/27421/\n# Accepted submission: 52735753\n# Source: http://cs101.openjudge.cn/practice/solution/52735753/\n# License: not declared on the submission page; no license is inferred.\n\nimport heapq\n\ndef main():\n    import sys\n    input = sys.stdin.read().split()\n    idx = 0\n    m = int(input[idx])\n    n = int(input[idx+1])\n    idx +=2\n\n    heightMap = []\n    for i in range(m):\n        row = list(map(int, input[idx:idx+n]))\n        idx +=n\n        heightMap.append(row)\n\n    # 最小堆 + 访问矩阵\n    heap = []\n    visited = [[False]*n for _ in range(m)]\n\n    # 放入四周边界\n    for i in range(m):\n        for j in range(n):\n            if i==0 or i==m-1 or j==0 or j==n-1:\n                heapq.heappush(heap, (heightMap[i][j], i, j))\n                visited[i][j] = True\n\n    # 四个方向\n    dirs = [(-1,0),(1,0),(0,-1),(0,1)]\n    res = 0\n    max_h = 0\n\n    while heap:\n        h, x, y = heapq.heappop(heap)\n        max_h = max(max_h, h)\n\n        for dx, dy in dirs:\n            nx = x + dx\n            ny = y + dy\n            if 0<=nx<m and 0<=ny<n and not visited[nx][ny]:\n                visited[nx][ny] = True\n                if heightMap[nx][ny] < max_h:\n                    res += max_h - heightMap[nx][ny]\n                heapq.heappush(heap, (heightMap[nx][ny], nx, ny))\n\n    print(res)\n\nif __name__ == "__main__":\n    main()'
